<?php include __DIR__.'/../partials/member-open.php'; ?>
<header class="member-heading"><div><span class="member-eyebrow">YANINIZDAYIZ</span><h1>Destek Merkezi</h1><p>Taleplerinizi ve destek ekibimizin yanıtlarını takip edin.</p></div><a class="member-btn" href="/destek/yeni"><?= icon('plus',16) ?> Yeni talep</a></header>
<form class="member-card member-filters is-support" method="get" action="/destek"><div><label for="member-ticket-query">Konu veya talep no</label><input id="member-ticket-query" class="member-control" name="q" type="search" value="<?= e($q) ?>" maxlength="80" placeholder="Destek taleplerinde ara…"></div><div><label for="member-ticket-status">Talep durumu</label><select id="member-ticket-status" class="member-control" name="status"><option value="">Tüm talepler</option><?php foreach(['open','answered','customer_reply','closed']as $s): ?><option value="<?= $s ?>" <?= $status===$s?'selected':'' ?>><?= e(supportStatusLabel($s)) ?></option><?php endforeach; ?></select></div><div class="member-filter-actions"><button type="submit" class="member-btn">Filtrele</button><a href="/destek" class="member-text-link">Temizle</a></div></form>
