<section class="member-card"><?php if(!$tickets): ?><div class="member-empty"><?= icon('headphones',36) ?><h2>Görüntülenecek talep bulunamadı.</h2><p>Bir sorunuz varsa siparişinize bağlı yeni bir destek talebi oluşturabilirsiniz.</p><a class="member-btn" href="/destek/yeni">Talep oluştur</a></div><?php else: foreach($tickets as $ticket): ?><a href="/destek/<?= (int)$ticket['id'] ?>" class="member-ticket"><span class="member-icon-soft"><?= icon('message-circle',20) ?></span><div><small>#<?= e($ticket['ticket_number']) ?></small><h2><?= e($ticket['subject']) ?></h2><p><?= formatDate($ticket['updated_at'],'d.m.Y H:i') ?> · <?= e(priorityLabel($ticket['priority'])) ?> öncelik<?= $ticket['order_id']?' · Sipariş bağlantılı':'' ?></p></div><span class="member-badge <?= in_array($ticket['status'],['answered','admin_reply'],true)?'is-success':'' ?>"><?= e(supportStatusLabel($ticket['status'])) ?></span><?= icon('chevron-right',17) ?></a><?php endforeach; endif; ?></section>
<?php if($totalPages>1): ?><nav class="member-pagination" aria-label="Destek talepleri sayfalama"><?php for($i=max(1,$page-2);$i<=min($totalPages,$page+2);$i++): ?><a href="<?= e('/destek?'.http_build_query(['q'=>$q,'status'=>$status,'page'=>$i])) ?>" <?= $i===$page?'aria-current="page"':'' ?>><?= $i ?></a><?php endfor; ?><span><?= $page ?> / <?= $totalPages ?></span></nav><?php endif; ?>
